create table public.accounts (id uuid, user_id uuid, provider text, provider_account_ref text, name text, base_currency text, mode text, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone);
create table public.fx_rates (id uuid, rate_date date, base_currency text, quote_currency text, rate numeric, source text, observed_at timestamp with time zone);
create table public.holdings (id uuid, account_id uuid, security_id uuid, as_of timestamp with time zone, quantity numeric, avg_cost numeric, market_price numeric, market_value numeric, unrealized_pnl numeric, unrealized_pnl_rate numeric, official_unrealized_pnl numeric, currency text, fx_rate_to_base numeric, source text, provider_payload jsonb, created_at timestamp with time zone, updated_at timestamp with time zone);
create table public.kb_position_evidence (id uuid, account_id uuid, source text, source_key text, asset_key text, symbol text, raw_type text, event_type text, order_date date, trade_date date, settlement_date date, quantity numeric, price numeric, gross_amount numeric, currency text, evidence jsonb, fetched_at timestamp with time zone, active boolean);
create table public.realized_pnl_events (id uuid, account_id uuid, security_id uuid, provider_event_id text, realized_date date, quantity numeric, sell_price numeric, buy_price numeric, sell_amount numeric, buy_amount numeric, fee numeric, tax numeric, realized_pnl numeric, return_rate numeric, currency text, source text, provider_payload jsonb, created_at timestamp with time zone, updated_at timestamp with time zone);
create table public.securities (id uuid, symbol text, name text, market text, asset_type text, currency text, sector text, country text, isin text, created_at timestamp with time zone, updated_at timestamp with time zone);
create table public.transactions (id uuid, account_id uuid, security_id uuid, external_id text, trade_at timestamp with time zone, settlement_at timestamp with time zone, type text, quantity numeric, price numeric, gross_amount numeric, fee numeric, tax numeric, net_amount numeric, currency text, fx_rate numeric, realized_pnl numeric, official_realized_pnl numeric, source text, provider_revision text, provider_payload_hash text, provider_payload jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, order_at timestamp with time zone, account_reflected_at timestamp with time zone, fetched_at timestamp with time zone, raw_type text, normalized_type text, position_delta numeric);
